<script setup>
defineProps({ columns: { type: Array, default: () => [] }, rows: { type: Array, default: () => [] }, caption: { type: String, required: true }, rowKey: { type: String, default: 'id' }, loading: Boolean, emptyText: { type: String, default: 'Không có dữ liệu.' } })
</script>
<template><div class="p-table-scroll" role="region" :aria-label="caption" tabindex="0" :aria-busy="loading || undefined"><table class="p-table"><caption>{{ caption }}</caption><thead><tr><th v-for="column in columns" :key="column.key" scope="col"><slot :name="`header-${column.key}`">{{ column.label }}</slot></th></tr></thead><tbody><tr v-if="loading"><td :colspan="columns.length" role="status">Đang tải dữ liệu…</td></tr><template v-else><tr v-for="row in rows" :key="row[rowKey]"><td v-for="column in columns" :key="column.key"><slot :name="`cell-${column.key}`" :row="row" :value="row[column.key]">{{ row[column.key] }}</slot></td></tr><tr v-if="!rows.length"><td :colspan="columns.length">{{ emptyText }}</td></tr></template></tbody></table></div></template>
